```javascript
function TreeNode(left, right) {
  this.left = left;
  this.right = right;
}

function bottomUpTree(depth) {
  if (depth > 0) {
    return new TreeNode(bottomUpTree(depth - 1), bottomUpTree(depth - 1));
  } else {
    return new TreeNode(null, null);
  }
}

function itemCheck(tree) {
  if (tree.left === null) {
    return 1;
  } else {
    return 1 + itemCheck(tree.left) + itemCheck(tree.right);
  }
}

function main() {
  const N = parseInt(process.argv[2], 10);

  const stretchDepth = N + 1;
  const stretchTree = bottomUpTree(stretchDepth);
  const stretchCheck = itemCheck(stretchTree);
  console.log(`stretch tree of depth ${stretchDepth}\t check: ${stretchCheck}`);

  const longLivedTree = bottomUpTree(N);

  for (let d = 4; d <= N; d += 2) {
    const iterations = 1 << (N - d + 4);
    let sum = 0;
    for (let i = 0; i < iterations; i++) {
      const tree = bottomUpTree(d);
      sum += itemCheck(tree);
    }
    console.log(`${iterations}\t trees of depth ${d}\t check: ${sum}`);
  }

  const longLivedCheck = itemCheck(longLivedTree);
  console.log(`long lived tree of depth ${N}\t check: ${longLivedCheck}`);
}

main();
```

