```javascript
const fs = require('fs');

const N = parseInt(process.argv[2], 10);

const ALU = 
  'GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA' +
  'TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT' +
  'AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG' +
  'GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG' +
  'CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA';

const ALU_CODES = new Uint8Array(ALU.length);
for (let i = 0; i < ALU.length; i++) {
  ALU_CODES[i] = ALU.charCodeAt(i);
}

const IUB_SYMS = ['a','c','g','t','B','D','H','K','M','N','R','S','V','W','Y'];
const IUB_PROBS = [0.27,0.12,0.12,0.27,0.02,0.02,0.02,0.02,0.02,0.02,0.02,0.02,0.02,0.02,0.02];
const HOMO_SYMS = ['a','c','g','t'];
const HOMO_PROBS = [0.3029549426680,0.1979883004921,0.1975473066391,0.3015094502008];

function buildCum(probs) {
  let c = 0;
  const cum = new Array(probs.length);
  for (let i = 0; i < probs.length; i++) {
    c += probs[i];
    cum[i] = c;
  }
  return cum;
}

function buildMap(syms, cum) {
  const map = new Uint8Array(139968);
  for (let s = 0; s < 139968; s++) {
    const r = s / 139968;
    let j = 0;
    while (r >= cum[j]) j++;
    map[s] = syms[j].charCodeAt(0);
  }
  return map;
}

const IUB_CUM = buildCum(IUB_PROBS);
const HOMO_CUM = buildCum(HOMO_PROBS);
const IUB_MAP = buildMap(IUB_SYMS, IUB_CUM);
const HOMO_MAP = buildMap(HOMO_SYMS, HOMO_CUM);

let seed = 42;

function writeALU(len) {
  const CHUNK = 60 * 1000;
  let written = 0;
  let aluPos = 0;
  while (written < len) {
    const chunkLen = Math.min(CHUNK, len - written);
    const numLines = Math.ceil(chunkLen / 60);
    const buf = Buffer.allocUnsafe(chunkLen + numLines);
    let pos = 0;
    for (let i = 0; i < chunkLen; i++) {
      buf[pos++] = ALU_CODES[aluPos];
      aluPos = (aluPos + 1) % ALU.length;
      if ((i + 1) % 60 === 0 || (i === chunkLen - 1 && chunkLen % 60 !== 0)) {
        buf[pos++] = 10;
      }
    }
    fs.writeSync(1, buf);
    written += chunkLen;
  }
}

function writeRandom(len, map) {
  const CHUNK = 60 * 1000;
  let written = 0;
  while (written < len) {
    const chunkLen = Math.min(CHUNK, len - written);
    const numLines = Math.ceil(chunkLen / 60);
    const buf = Buffer.allocUnsafe(chunkLen + numLines);
    let pos = 0;
    for (let i = 0; i < chunkLen; i++) {
      seed = (seed * 3877 + 29573) % 139968;
      buf[pos++] = map[seed];
      if ((i + 1) % 60 === 0 || (i === chunkLen - 1 && chunkLen % 60 !== 0)) {
        buf[pos++] = 10;
      }
    }
    fs.writeSync(1, buf);
    written += chunkLen;
  }
}

fs.writeSync(1, '>ONE Homo sapiens alu\n');
writeALU(2 * N);
fs.writeSync(1, '>TWO IUB ambiguity codes\n');
writeRandom(3 * N, IUB_MAP);
fs.writeSync(1, '>THREE Homo sapiens frequency\n');
writeRandom(5 * N, HOMO_MAP);
