const fs = require('fs');

const comp = new Array(256);
for (let i = 0; i < 256; i++) comp[i] = String.fromCharCode(i);
const map = {
    'A':'T', 'T':'A', 'C':'G', 'G':'C', 'U':'A',
    'R':'Y', 'Y':'R', 'K':'M', 'M':'K', 'B':'V', 'V':'B',
    'D':'H', 'H':'D', 'S':'S', 'W':'W', 'N':'N',
    'a':'t', 't':'a', 'c':'g', 'g':'c', 'u':'a',
    'r':'y', 'y':'r', 'k':'m', 'm':'k', 'b':'v', 'v':'b',
    'd':'h', 'h':'d', 's':'s', 'w':'w', 'n':'n'
};
for (const [k, v] of Object.entries(map)) {
    comp[k.charCodeAt(0)] = v;
}

function main() {
    const data = fs.readFileSync(0, 'utf8');
    const lines = data.split('\n');
    const records = [];
    let currentHeader = null;
    let currentSeq = [];
    let currentLengths = [];

    for (let i = 0; i < lines.length; i++) {
        let line = lines[i];
        if (line.endsWith('\r')) line = line.slice(0, -1);
        if (line.length === 0) continue;
        if (line[0] === '>') {
            if (currentHeader !== null) {
                records.push({ header: currentHeader, seq: currentSeq.join(''), lengths: currentLengths });
            }
            currentHeader = line;
            currentSeq = [];
            currentLengths = [];
        } else {
            if (currentHeader !== null) {
                currentSeq.push(line);
                currentLengths.push(line.length);
            }
        }
    }
    if (currentHeader !== null) {
        records.push({ header: currentHeader, seq: currentSeq.join(''), lengths: currentLengths });
    }

    const out = [];
    for (const rec of records) {
        out.push(rec.header);
        const seq = rec.seq;
        const len = seq.length;
        const revComp = new Array(len);
        for (let i = 0; i < len; i++) {
            revComp[len - 1 - i] = comp[seq.charCodeAt(i)];
        }
        const revCompStr = revComp.join('');
        const revLengths = rec.lengths.slice().reverse();
        let pos = 0;
        for (const l of revLengths) {
            out.push(revCompStr.slice(pos, pos + l));
            pos += l;
        }
    }
    if (out.length > 0) {
        process.stdout.write(out.join('\n') + '\n');
    }
}

main();
```

